"""Focused Playwright script body used for RetentionAdvisorModal bug verification.

This file stores the exact async body passed to mcp_browser_automation, which runs it
inside an existing Playwright page context.
"""

PLAYWRIGHT_SCRIPT = r'Focused Playwright test body for RetentionAdvisorModal bug verification.\nExecuted via mcp_browser_automation against /finance.\n"""\n\ntry:\n    await page.set_viewport_size({"width": 1920, "height": 1080})\n    print("STEP 1: viewport set to desktop 1920x1080")\n\n    advisor_request_count = {"count": 0}\n\n    async def delay_advisor_request(route):\n        advisor_request_count["count"] += 1\n        print(f"STEP 2: delaying real advisor request #{advisor_request_count[\'count\']} by 1000ms to verify initial loader")\n        await page.wait_for_timeout(1000)\n        await route.continue_()\n\n    await page.route("**/api/v1/ai/retention-advisor", delay_advisor_request)\n\n    await page.goto("https://abyns-demo.preview.emergentagent.com/finance", wait_until="domcontentloaded")\n    await page.wait_for_load_state("networkidle", timeout=20000)\n    print("STEP 3: /finance loaded")\n\n    ask_btn = page.get_by_test_id("ask-advisor-btn")\n    await ask_btn.scroll_into_view_if_needed()\n    await expect(ask_btn).to_be_visible(timeout=15000)\n    await ask_btn.click()\n    print("STEP 4: clicked Tanya ABYNS AI")\n\n    modal = page.get_by_test_id("advisor-modal")\n    await expect(modal).to_be_visible(timeout=5000)\n    print("STEP 5: advisor modal visible")\n\n    await page.wait_for_timeout(150)\n    loader_line_count = await modal.locator(".advisor-loader-line").count()\n    loader_text_visible = await modal.get_by_text("ABYNS AI sedang menganalisa data churn Anda...", exact=True).is_visible()\n    spinner_count = await modal.locator(".advisor-loader .qris-rotate").count()\n    initial_error_text = await page.evaluate("""() => {\n      const modal = document.querySelector(\'[data-testid="advisor-modal"]\');\n      return modal ? modal.innerText.includes(\'Gagal memuat analisa\') : false;\n    }""")\n    print(f"STEP 6: initial loader check within delayed request window: loader_lines={loader_line_count}, loader_text_visible={loader_text_visible}, spinner_count={spinner_count}, initial_error_present={initial_error_text}")\n    assert loader_line_count >= 4, "Expected shimmer skeleton loader lines during initial loading"\n    assert loader_text_visible, "Expected ABYNS AI loading text during initial loading"\n    assert spinner_count >= 1, "Expected spinning icon during initial loading"\n    assert not initial_error_text, "Red error text appeared during initial loading"\n\n    dom_order = await page.evaluate("""() => {\n      const scroll = document.querySelector(\'[data-testid="advisor-modal"] .advisor-scroll\');\n      const actions = scroll?.querySelector(\'.advisor-actions-grid\');\n      const analysis = scroll?.querySelector(\'.advisor-analysis-card\');\n      const actionButtons = Array.from(document.querySelectorAll(\'[data-testid^="advisor-run-"]\')).map(el => el.getAttribute(\'data-testid\'));\n      return {\n        hasScroll: !!scroll,\n        hasActions: !!actions,\n        hasAnalysis: !!analysis,\n        actionsBeforeAnalysis: !!(actions && analysis && (actions.compareDocumentPosition(analysis) & Node.DOCUMENT_POSITION_FOLLOWING)),\n        actionButtonCount: actionButtons.length,\n        actionButtons\n      };\n    }""")\n    print(f"STEP 7: DOM order/action card check: {dom_order}")\n    assert dom_order["hasScroll"] and dom_order["hasActions"] and dom_order["hasAnalysis"], "Expected advisor scroll, actions grid, and analysis card"\n    assert dom_order["actionsBeforeAnalysis"], "Actions grid must appear before AI analysis card"\n    assert dom_order["actionButtonCount"] == 3, "Expected exactly 3 action card buttons"\n\n    layout_initial = await page.evaluate("""() => {\n      const modal = document.querySelector(\'[data-testid="advisor-modal"]\');\n      const scroll = modal?.querySelector(\'.advisor-scroll\');\n      const ms = modal ? getComputedStyle(modal) : null;\n      const ss = scroll ? getComputedStyle(scroll) : null;\n      return {\n        modalClass: modal?.className,\n        maxHeight: ms?.maxHeight,\n        display: ms?.display,\n        flexDirection: ms?.flexDirection,\n        modalHeight: modal?.getBoundingClientRect().height,\n        viewportHeight: window.innerHeight,\n        scrollOverflowY: ss?.overflowY,\n        scrollClientHeight: scroll?.clientHeight,\n        scrollHeight: scroll?.scrollHeight\n      };\n    }""")\n    print(f"STEP 8: initial modal layout computed styles: {layout_initial}")\n\n    await expect(modal.locator(".advisor-analysis-head").get_by_text("selesai", exact=True)).to_be_visible(timeout=15000)\n    print("STEP 9: AI stream completed and selesai badge visible")\n\n    analysis_text = await modal.locator(".advisor-analysis-body").inner_text(timeout=5000)\n    analysis_excerpt = analysis_text[:500].replace("\\n", " ")\n    print(f"STEP 10: analysis text length={len(analysis_text)} excerpt={analysis_excerpt}")\n    assert len(analysis_text.strip()) >= 80, "Expected populated AI analysis text"\n    assert any(keyword.lower() in analysis_text.lower() for keyword in ["retention", "diagnosis", "diagnosa", "tindakan", "target", "churn"]), "Analysis text should mention retention/diagnosis/tindakan/target/churn"\n\n    # Scroll the internal body after content is loaded; footer/header controls should remain usable/visible.\n    layout_after_stream = await page.evaluate("""() => {\n      const modal = document.querySelector(\'[data-testid="advisor-modal"]\');\n      const scroll = modal?.querySelector(\'.advisor-scroll\');\n      if (scroll) scroll.scrollTop = scroll.scrollHeight;\n      const ms = modal ? getComputedStyle(modal) : null;\n      const ss = scroll ? getComputedStyle(scroll) : null;\n      const close = document.querySelector(\'[data-testid="advisor-close"]\');\n      const done = document.querySelector(\'[data-testid="advisor-done"]\');\n      const copy = document.querySelector(\'[data-testid="advisor-copy"]\');\n      const closeRect = close?.getBoundingClientRect();\n      const doneRect = done?.getBoundingClientRect();\n      const copyRect = copy?.getBoundingClientRect();\n      return {\n        maxHeight: ms?.maxHeight,\n        display: ms?.display,\n        flexDirection: ms?.flexDirection,\n        modalHeight: modal?.getBoundingClientRect().height,\n        viewportHeight: window.innerHeight,\n        scrollOverflowY: ss?.overflowY,\n        scrollTop: scroll?.scrollTop,\n        scrollClientHeight: scroll?.clientHeight,\n        scrollHeight: scroll?.scrollHeight,\n        closeVisibleInViewport: !!closeRect && closeRect.top >= 0 && closeRect.bottom <= window.innerHeight,\n        doneVisibleInViewport: !!doneRect && doneRect.top >= 0 && doneRect.bottom <= window.innerHeight,\n        copyVisibleInViewport: !!copyRect && copyRect.top >= 0 && copyRect.bottom <= window.innerHeight\n      };\n    }""")\n    print(f"STEP 11: post-stream layout/visibility after internal scroll: {layout_after_stream}")\n\n    assert layout_after_stream["display"] == "flex", "advisor modal should be flex column"\n    assert layout_after_stream["flexDirection"] == "column", "advisor modal should have column flex direction"\n    assert layout_after_stream["maxHeight"] not in [None, "none", "0px"], "advisor modal should have max-height (88vh)"\n    assert layout_after_stream["modalHeight"] <= layout_after_stream["viewportHeight"] * 0.93, "advisor modal should fit within viewport, around 88vh"\n    assert layout_after_stream["scrollOverflowY"] == "auto", "advisor-scroll should scroll internally"\n    assert layout_after_stream["closeVisibleInViewport"], "header close button should remain visible"\n    assert layout_after_stream["doneVisibleInViewport"], "footer done button should remain visible"\n    assert layout_after_stream["copyVisibleInViewport"], "footer copy button should remain visible after AI text is loaded"\n\n    run_btn = page.get_by_test_id("advisor-run-preventive_maintenance")\n    await run_btn.scroll_into_view_if_needed()\n    await expect(run_btn).to_be_visible(timeout=5000)\n    await run_btn.click()\n    print("STEP 12: clicked preventive maintenance Jalankan")\n    result = page.get_by_test_id("advisor-result-preventive_maintenance")\n    await expect(result).to_be_visible(timeout=10000)\n    result_text = await result.inner_text()\n    print(f"STEP 13: preventive maintenance result text={result_text}")\n    assert "3 tugas dibuat" in result_text, "Expected success state with \'3 tugas dibuat.\'"\n\n    await page.get_by_test_id("advisor-close").click()\n    await expect(modal).not_to_be_visible(timeout=5000)\n    print("STEP 14: modal closed cleanly via X")\n\n    # Get error messages using specific selectors\n    error_text = await page.evaluate("""() => {\n    const errorElements = Array.from(document.querySelectorAll(\'.error, [class*="error"], [id*="error"]\'));\n    return errorElements.map(el => el.textContent).join(", ");\n    }""")\n    if error_text:\n        print(f"Found error message: {error_text}")\n    else:\n        print("No error messages found on the page")\n\n    print("TEST RESULT: PASS - Retention advisor modal flow verified")\nexcept Exception as e:\n    print(f"TEST RESULT: FAIL - {type(e).__name__}: {e}")\n    # Get error messages using specific selectors\n    error_text = await page.evaluate("""() => {\n    const errorElements = Array.from(document.querySelectorAll(\'.error, [class*="error"], [id*="error"]\'));\n    return errorElements.map(el => el.textContent).join(", ");\n    }""")\n    if error_text:\n        print(f"Found error message: {error_text}")\n    else:\n        print("No error messages found on the page")\n    raise'
